//! User-facing log management (#1060): enumerate every managed log stream, read a stream's raw
//! tail, clear or export a stream, and a config-driven size/line cap.
//!
//! The six `bsc-*` TSVs (`coord`/`audit`/`skills`/`hooks`/`mcp`/`tokens`) and the rotating
//! application log are flat text — viewable, exportable, and cappable here. `perf.db` is binary
//! state: it's listed for size/mtime, but cleared from the Performance tab (`perf_clear_history`)
//! and never raw-viewed. `plan.db` is project STATE and is deliberately NOT managed here.

use self::label_for::label_for;
use crate::StrErr;
use crate::platform::offmain::blocking_or;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};
use tauri::Manager;

use super::MutexConfig;
use crate::bsc_base_dir;

// ── Config ──────────────────────────────────────────────────────────────────────

/// User-controlled retention for the text log streams. `0` disables a cap. Mirrors the
/// `PerfConfig` pattern: held in memory (default until the frontend pushes the persisted value via
/// `log_set_config`) and applied by `cap_logs`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LogConfig {
    /// Trim a text log to its newest N lines on enforcement. 0 = no line cap.
    pub max_lines: u32,
    /// Trim a text log to its newest bytes if it exceeds this many MB. 0 = no size cap.
    pub max_size_mb: u32,
}

impl Default for LogConfig {
    /// 10k lines preserves the historical `perf::cap_logs` behaviour; 20 MB is a generous byte
    /// backstop for a log whose lines are unusually long.
    fn default() -> Self {
        Self { max_lines: 10_000, max_size_mb: 20 }
    }
}

/// The text-log retention config, held in a poison-tolerant `Mutex`. Built on the shared
/// `MutexConfig<T>` (config-in-mutex + `get`/`set`); `perf`'s `PerfState` shares only the
/// underlying `lock_recover` idiom since it carries more than a config.
pub type LogState = MutexConfig<LogConfig>;

// ── Stream registry ─────────────────────────────────────────────────────────────

// The managed text-log streams are the SAME per-pane TSVs the pty env-writer stages and the unified
// `bsc logs` reader parses — `bsc_util::LOG_STREAMS`, the ONE source of truth for stream keys +
// filenames (#1847). This module no longer keeps its own `(key, file)` table, which had drifted out
// of sync (it was missing `activity`/`done`/`perm`, so those growing logs were neither listed, capped,
// clearable, nor viewable here). The engine that PARSES these streams lives in `crates/logs` and is
// reached from the frontend via `bsc logs …` over the `bsc` bridge (#2144); this module owns only the
// file-management face — inventory, size cap, clear, export, and the raw viewer (which also serves the
// Tauri-owned `app` log). Labels are a UI concern kept here, keyed by the registry's canonical key.


/// Resolve a stream key to its on-disk path. The app log lives in Tauri's log dir; `perf.db` and
/// the TSVs live under `~/.base-studio-code/`. The TSV filenames come from the shared
/// `bsc_util::LOG_STREAMS` registry. Returns `None` for unknown/excluded keys.
fn stream_path(app: &tauri::AppHandle, stream: &str) -> Option<PathBuf> {
    match stream {
        "app" => app.path().app_log_dir().ok().map(|d| d.join("base-studio-code.log")),
        "perf" => Some(crate::perf_db()),
        other => bsc_util::LOG_STREAMS
            .iter()
            .find(|s| s.key == other)
            .map(|s| bsc_base_dir().join(s.filename)),
    }
}

/// Whether a stream is flat text (raw-viewable / cappable). `perf.db` is binary state.
fn is_text(stream: &str) -> bool {
    stream != "perf"
}

/// The rotating application log path (`<app_log_dir>/base-studio-code.log`) — the file the
/// [`GraphLogger`](crate::observability::graph_log) file sink appends to and the `"app"` reader
/// stream consumes. Exposed so the cap paths can rotate it now that no plugin does (#1389).
pub fn app_log_file(app: &tauri::AppHandle) -> Option<PathBuf> {
    stream_path(app, "app")
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct LogFileInfo {
    pub stream: String,
    pub label: String,
    pub path: String,
    pub size_bytes: u64,
    /// Last-modified, ms since the Unix epoch; 0 when the file is absent/unreadable.
    pub mtime_ms: i64,
    pub exists: bool,
    pub text: bool,
}

fn mtime_ms(path: &Path) -> i64 {
    std::fs::metadata(path)
        .and_then(|m| m.modified())
        .ok()
        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_millis() as i64)
        .unwrap_or(0)
}

fn info(app: &tauri::AppHandle, stream: &str) -> LogFileInfo {
    let label = label_for(stream);
    let path = stream_path(app, stream);
    let (size, mtime, exists, path_str) = match &path {
        Some(p) if p.exists() => (
            std::fs::metadata(p).map(|m| m.len()).unwrap_or(0),
            mtime_ms(p),
            true,
            p.to_string_lossy().into_owned(),
        ),
        Some(p) => (0, 0, false, p.to_string_lossy().into_owned()),
        None => (0, 0, false, String::new()),
    };
    LogFileInfo {
        stream: stream.to_string(),
        label: label.to_string(),
        path: path_str,
        size_bytes: size,
        mtime_ms: mtime,
        exists,
        text: is_text(stream),
    }
}

// ── Capping ─────────────────────────────────────────────────────────────────────

/// Trim a text log to the newest `max_lines` lines and, if still over `max_size_mb`, drop further
/// oldest lines until under the byte cap. In-place; no-ops on a missing/short file or all-zero
/// config. Returns whether it rewrote the file (for tests).
pub fn cap_log(path: &Path, cfg: &LogConfig) -> bool {
    let Ok(text) = std::fs::read_to_string(path) else { return false };
    let mut lines: Vec<&str> = text.lines().collect();
    let original = lines.len();

    if cfg.max_lines > 0 && lines.len() > cfg.max_lines as usize {
        lines = lines.split_off(lines.len() - cfg.max_lines as usize);
    }
    if cfg.max_size_mb > 0 {
        let cap = cfg.max_size_mb as usize * 1024 * 1024;
        // Drop oldest lines (cheaply, by byte length + newline) until under the cap.
        let mut bytes: usize = lines.iter().map(|l| l.len() + 1).sum();
        let mut drop = 0;
        while bytes > cap && drop < lines.len() {
            bytes -= lines[drop].len() + 1;
            drop += 1;
        }
        if drop > 0 {
            lines = lines.split_off(drop);
        }
    }

    if lines.len() == original {
        return false; // nothing trimmed
    }
    let out = if lines.is_empty() { String::new() } else { lines.join("\n") + "\n" };
    if std::fs::write(path, out.as_bytes()).is_ok() {
        log::info!("logs: capped {} from {} to {} lines", path.display(), original, lines.len());
        true
    } else {
        false
    }
}

/// Cap every managed text TSV stream (the shared `bsc_util::LOG_STREAMS` registry) under `base_dir`
/// per `cfg`. The rotating application log lives in Tauri's `app_log_dir` and is capped separately
/// via [`cap_log`] on [`app_log_file`] (the boot cap + "Enforce now" do so now that the custom
/// `GraphLogger` (#1389) owns it — no plugin rotates it); `perf.db` is binary state pruned by the
/// perf sampler, not here.
pub fn cap_logs(base_dir: &Path, cfg: &LogConfig) {
    for s in bsc_util::LOG_STREAMS {
        let p = base_dir.join(s.filename);
        if p.exists() {
            cap_log(&p, cfg);
        }
    }
}

// ── Tauri commands ──────────────────────────────────────────────────────────────

/// Every managed stream's path/size/mtime: the app log, every `bsc_util::LOG_STREAMS` per-pane TSV,
/// and `perf.db`.
#[tauri::command]
pub fn list_log_files(app: tauri::AppHandle) -> Vec<LogFileInfo> {
    let mut out = vec![info(&app, "app")];
    for s in bsc_util::LOG_STREAMS {
        out.push(info(&app, s.key));
    }
    out.push(info(&app, "perf"));
    out
}

/// The newest `limit` non-blank lines of a text log file. `newest_first` selects the order:
/// `true` returns them newest-first (the audit/skill/hook/mcp readers); `false` keeps the file's
/// chronological oldest-first order (the coord log + `read_log_tail`). A missing/unreadable file
/// yields an empty list. The one copy of the six near-identical tail readers' body.
pub(crate) fn tail_lines(path: &Path, limit: usize, newest_first: bool) -> Vec<String> {
    let text = std::fs::read_to_string(path).unwrap_or_default();
    let mut lines: Vec<String> =
        text.lines().filter(|l| !l.trim().is_empty()).map(str::to_string).collect();
    if newest_first {
        lines.reverse();
        lines.truncate(limit);
    } else if lines.len() > limit {
        lines = lines.split_off(lines.len() - limit);
    }
    lines
}

/// The newest `limit` raw lines of a text stream, in chronological order (oldest of the tail
/// first). Empty for `perf.db` (binary) or an unknown/missing stream.
#[tauri::command]
pub async fn read_log_tail(stream: String, limit: usize, app: tauri::AppHandle) -> Vec<String> {
    // `stream_path` needs the AppHandle but is cheap; resolve it here and move only the PathBuf, so
    // the blocking closure owns nothing tied to the caller.
    if !is_text(&stream) {
        return Vec::new();
    }
    let Some(path) = stream_path(&app, &stream) else { return Vec::new() };
    blocking_or("read_log_tail", Vec::new(), move || tail_lines(&path, limit, false)).await
}

// The per-stream TSV log readers (`read_audit_log`/`read_skill_log`/`read_hook_log`/`read_mcp_log`/
// `read_coord_log`) moved to the `bsc logs tail <stream>` CLI over the `bsc` bridge (#2144). The
// underlying `tail_lines` reader stays — it still backs `read_log_tail` (the raw-viewer command,
// which also serves the Tauri-owned `app` log and so cannot move to `bsc logs`).

// ── In-process hot-poll readers (#3630) ──────────────────────────────────────────
//
// The always-on fleet/console pumps (`useCoordLog`, `useWorkerAutoEnd`, the pane-activity poll, the
// coordination pumps) read these unified streams every ~1s. Routing each poll through the `bsc`
// bridge SPAWNED a `bsc.exe` subprocess per read (`console::bsc`), and at 5–10 spawns/sec the Tauri
// invoke backlog grew without bound → the app progressively froze. These commands read the SAME
// streams IN-PROCESS via the already-linked `logs` crate — no spawn, no per-call DB/binary init — so
// the hot polls cost a file read instead of a process. They resolve the log dir with `logs::log_dir`,
// the exact resolver the `bsc logs` CLI uses (`$BSC_LOG_DIR`, else `~/.base-studio-code`), so they
// read byte-for-byte the same files the subprocess did. #4074 brought `cost` across too — it was
// filed here as "low-frequency" and is in fact polled every 4s, the app's biggest spawner. The
// remaining analytics one-shots stay on the bridge.

/// Newest `limit` raw lines of a unified `bsc logs` stream (`coord`/`audit`/`skill`/`hook`/`mcp`/`ui`/
/// `perm`), read in-process (#3630) — the drop-in for `bsc logs tail <stream> --json`. `oldest` keeps
/// chronological order (the coord log); otherwise newest-first. Unknown/missing stream ⇒ empty.
#[tauri::command]
pub async fn logs_tail(stream: String, limit: usize, oldest: bool) -> Vec<String> {
    blocking_or("logs_tail", Vec::new(), move || {
        ::logs::tail_raw(&::logs::log_dir(), &stream, limit, oldest)
    })
    .await
}

/// Per-pane token + cost rollup, newest pane first — the in-process drop-in for
/// `bsc logs cost --full --limit N --json` (#4074), calling the SAME `logs::cost::usage` the CLI's
/// `cost` verb does, so the rows are byte-identical.
///
/// #3630 moved the hot pollers in-process and left the cost read on the `bsc` bridge as
/// "low-frequency". It is not: `usePaneTokenUsage` polls it every 4s, and it was the single biggest
/// process spawner in the app — 415 calls in a 27-minute window, more than any other command. Each
/// spawn blocked Tauri's main thread, so the invoke queue backed up to 25s and every other command,
/// including trivial ones like `perf_record_frontend_sample`, waited behind it.
#[tauri::command]
pub async fn logs_usage(limit: usize) -> Vec<::logs::Usage> {
    blocking_or("logs_usage", Vec::new(), move || ::logs::usage(&::logs::log_dir(), limit)).await
}

/// The fields the Algorithms page actually renders, and the ONLY ones [`graph_dump`] ships.
///
/// Derived from the page, not guessed: `AlgorithmsInspector`, `AlgorithmsKitGraph`, `AlgorithmsRail`,
/// `classifyKind`, `crossGraphAdapter` and `knowledge.tsx` between them read these and nothing else.
///
/// # `code` IS NOT HERE, and that is the largest part of the fix
///
/// Bodies are 19.31 MB of the 20.26 MB that remained after `history` and `tests` came out — 1,401
/// bodies shipped to render ONE, because the inspector shows the SELECTED record's source and nothing
/// else does. [`graph_impl_source`] fetches that one on demand, which is 55x less on the load that has
/// to succeed for the page to come up at all.
///
/// The measured cost is 74 records whose `kind` came from `classifyKind`'s code fallback rather than
/// from their name — and every one of them is an app module (`console.ts`, `binding.ts`,
/// `graph-modules.ts`) matched because its body contains the word `swap`. Losing those classifications
/// removes false positives; the real algorithms are all classified by name, id and tags.
///
/// WHAT IS DELIBERATELY ABSENT is the point. `history` and `tests` are 30.36 MB of the 50.72 MB
/// document (MEASURED 2026-09-08 over 1,401 records) and the page does not read one byte of either:
/// `history` is write bookkeeping the committed store strips on promote anyway, and `tests` is carried
/// test SOURCE, which belongs to a test runner and not to a graph view. The write stamps
/// (`rev`/`updatedAt`/`updatedBy`/`build`) go with them.
///
/// An ALLOW-LIST rather than a deny-list, because the failure directions are not symmetric: a field
/// this list forgets is a rendering bug you see immediately, while a new unbounded field a deny-list
/// forgets is another 16 MB on a 5-second poll that nothing reports.
const PAGE_FIELDS: &[&str] = &[
    "id", "name", "role", "tech", "composes", "summary", "ref", "folder", "tags", "src",
    "domain", "feature", "kind", "provides", "suppressed", "supersededBy", "moduleState",
];

/// One record projected to [`PAGE_FIELDS`], plus a hash of the source the projection drops.
///
/// # `codeHash` is what keeps the body edit visible
///
/// Dropping `code` from the index removes 19.31 MB and, without this, would also remove the page's
/// only way to notice a body changing: `bsc graph impl set` moves `code`, `rev`, `updatedAt` and
/// `history`, and the projection drops every one of them — so a body-only edit would produce an
/// IDENTICAL signature, the poll would short-circuit forever, and the inspector would keep serving
/// whatever `graph_impl_source` returned first. A librarian editing a record live is the exact case
/// this page's 5-second poll exists for, so that is not an acceptable limit.
///
/// 64 hex characters per record — ~100 KB across 1,401 — buys it back: the signature moves, the poll
/// fetches, and `useImplSource` re-reads the one body that changed.
fn page_record(rec: &serde_json::Value) -> serde_json::Value {
    let Some(obj) = rec.as_object() else { return rec.clone() };
    let mut out: serde_json::Map<String, serde_json::Value> = obj
        .iter()
        .filter(|(k, _)| PAGE_FIELDS.contains(&k.as_str()))
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    let body = |key: &str| obj.get(key).and_then(serde_json::Value::as_str).unwrap_or_default();
    let source = format!("{}\u{1e}{}", body("code"), body("vizCode"));
    if source.len() > 1 {
        out.insert(
            "codeHash".to_string(),
            serde_json::Value::String(bsc_cli_util::vendored::sha256_hex(source.as_bytes())),
        );
    }
    serde_json::Value::Object(out)
}

/// The whole document projected to what the page renders — implementations and edges alike.
///
/// Separated from the command so a test can drive it without a Tauri runtime or the user's store.
pub(crate) fn page_projection(mut doc: serde_json::Value) -> serde_json::Value {
    if let Some(list) = doc.get_mut("implementations").and_then(|v| v.as_array_mut()) {
        for rec in list.iter_mut() {
            *rec = page_record(rec);
        }
    }
    doc
}

/// A cheap content signature over the projection — what changes when an edit lands, and nothing else.
///
/// This is what makes the 5-second poll affordable. The frontend hook already computes a signature to
/// decide whether to re-render, but it did so AFTER receiving the whole document, so the common case —
/// "nothing changed", which this command's own comment calls overwhelmingly common — still paid the
/// full transfer. Comparing signatures FIRST turns that case into a few dozen bytes.
///
/// Over the PROJECTION, not the raw store, so a write that only touched `history` (which every write
/// touches) does not read as a change the page must re-render for.
pub(crate) fn page_signature(doc: &serde_json::Value) -> String {
    // `bsc_cli_util::vendored::sha256_hex` — the ONE content-hash form in this workspace, reused rather
    // than restated so a second spelling of "the hash of this thing" cannot drift from the first.
    bsc_cli_util::vendored::sha256_hex(serde_json::to_string(doc).unwrap_or_default().as_bytes())
}

/// The algorithms knowledge graph, read IN-PROCESS — the drop-in for `bsc graph dump` (#4078).
///
/// `useKnowledgeGraph` polls this every 5s while the Algorithms page is mounted, and through the
/// `bsc` bridge every tick was a process SPAWN — to read 84 KB, hash it, and throw the result away
/// because nothing had changed, which is the overwhelmingly common case. Same mistake #3630 fixed for
/// the log pollers and #4074 for the cost poll.
///
/// Calls `bsc_graph::load`, the CLI's own reader, so it resolves the same store (`BSC_GRAPH_STORE`,
/// else `~/.base-studio-code/knowledge/algorithms.json`) and applies the same seed reconcile (#3198).
/// A missing/unreadable store yields the packaged seed, exactly as the CLI does — so the page keeps
/// rendering rather than blanking.
///
/// # It is PROJECTED now, and the 84 KB above is why
///
/// That comment was true when it was written and is the whole bug. The store is now 50.72 MB
/// (MEASURED 2026-09-08, 1,401 records) — 600x — and this command was still returning all of it every
/// five seconds, 609 MB/min through the webview, to a page that reads 0.93 MB of it. When that
/// transfer fails, `loadGraph` returns `null` and the hook silently KEEPS the packaged seed, so the
/// symptom is not an error: it is a graph that quietly shows 757 records instead of 1,401.
///
/// [`page_projection`] drops what the page does not read. A caller that genuinely wants the whole
/// document — history, carried tests and all — has `bsc graph dump`, which is the CLI surface for it
/// and is not on a 5-second timer.
#[tauri::command]
pub async fn graph_dump() -> serde_json::Value {
    // The fallback is `null`, which the frontend loader already treats as "no graph yet" — the same
    // degradation an unreadable store produces.
    blocking_or("graph_dump", serde_json::Value::Null, || {
        // THE DATABASE ANSWERS THIS DIRECTLY (`epic-retire-json-ledgers-for-db-and-git-drivers`).
        // `index` reads the page's fields off STORED columns — no body is parsed for a record the page
        // is only going to list — which is what a JSON blob structurally could not do and why this
        // command used to hand the webview the whole 50.76 MB document.
        if let Some(db) = bsc_graph::graph_db() {
            if let Ok(rows) = bsc_graph_store::index(&db) {
                if !rows.is_empty() {
                    return serde_json::json!({ "version": 1, "implementations": rows });
                }
            }
        }
        page_projection(bsc_graph::load())
    })
    .await
}

/// The projection's signature, without the projection — the poll's cheap first question.
///
/// Returns `null` on failure, which the caller treats as "cannot tell", falling through to a full
/// read rather than assuming nothing changed. Guessing "unchanged" on an error is how a store edit
/// would stop showing up entirely.
/// Every record that PROVIDES a specifier, with its source — what `resolveGraphSource` matches against.
///
/// # This is a different consumer from [`graph_dump`], and conflating them broke the app
///
/// `resolveGraphSource` turns a graph-hosted module's `@/…` import into source by finding the record
/// whose `provides` equals the specifier and vendoring its `code`. It reads that from the app store,
/// filled once at boot by `hydrateAlgorithms`, which used to call the same `graph_dump` the Algorithms
/// page polls. So when `graph_dump` stopped shipping bodies to make the page's 5-second poll
/// affordable, EVERY record-provided module across the app stopped resolving — including the ones the
/// Algorithms page is itself built from, which is why the page did not merely lose records, it stopped
/// loading. One command serving a page's rendering needs and the module loader's resolution needs is
/// the mistake; these are now two.
///
/// SCOPED TO RECORDS THAT PROVIDE SOMETHING, because that is all the resolver can ever match: 661 of
/// 1,402, and 4.32 MB against the 50.76 MB the whole document costs. Read ONCE at boot, not polled.
#[tauri::command]
pub async fn graph_modules() -> serde_json::Value {
    blocking_or("graph_modules", serde_json::Value::Null, || {
        // Indexed on `provides`, so this touches only the records that can ever match rather than all
        // of them — a different question from `graph_dump`, and serving both from one read is what
        // took the app down.
        if let Some(db) = bsc_graph::graph_db() {
            if let Ok(rows) = bsc_graph_store::modules(&db) {
                if !rows.is_empty() {
                    return serde_json::json!({ "implementations": rows });
                }
            }
        }
        modules_projection(&bsc_graph::load())
    })
    .await
}

/// [`graph_modules`]' projection, separated so a test can drive it without a Tauri runtime or a store.
pub(crate) fn modules_projection(doc: &serde_json::Value) -> serde_json::Value {
    let empty = Vec::new();
    let list = doc.get("implementations").and_then(|v| v.as_array()).unwrap_or(&empty);
    let mods: Vec<serde_json::Value> = list
        .iter()
        .filter(|r| {
            r.get("provides").and_then(serde_json::Value::as_str).is_some_and(|s| !s.trim().is_empty())
        })
        .map(|r| {
            serde_json::json!({
                "id": r.get("id").cloned().unwrap_or(serde_json::Value::Null),
                "provides": r.get("provides").cloned().unwrap_or(serde_json::Value::Null),
                "code": r.get("code").cloned().unwrap_or(serde_json::Value::Null),
            })
        })
        .collect();
    serde_json::json!({ "implementations": mods })
}

/// ONE record's source — `code` and `vizCode` — by id, or `null` when the store has no such record.
///
/// The other half of taking bodies out of [`graph_dump`]. The inspector renders the selected record's
/// source, so it needs exactly one body at a time; shipping all 1,401 to render one is what made the
/// page's hydrate unaffordable in the first place.
#[tauri::command]
pub async fn graph_impl_source(id: String) -> serde_json::Value {
    blocking_or("graph_impl_source", serde_json::Value::Null, move || {
        // A point read by id — 0.0 ms measured, against loading every record to find one.
        if let Some(db) = bsc_graph::graph_db() {
            if let Ok(Some(rec)) = bsc_graph_store::source(&db, &id) {
                return rec;
            }
        }
        let doc = bsc_graph::load();
        let Some(list) = doc.get("implementations").and_then(|v| v.as_array()) else {
            return serde_json::Value::Null;
        };
        let Some(rec) = list.iter().find(|r| r.get("id").and_then(|v| v.as_str()) == Some(id.as_str()))
        else {
            return serde_json::Value::Null;
        };
        serde_json::json!({
            "id": id,
            "code": rec.get("code").cloned().unwrap_or(serde_json::Value::Null),
            "vizCode": rec.get("vizCode").cloned().unwrap_or(serde_json::Value::Null),
        })
    })
    .await
}

#[tauri::command]
pub async fn graph_sig() -> serde_json::Value {
    blocking_or("graph_sig", serde_json::Value::Null, || {
        // Over the ledger's (id, rev) heads: a rev moves if and only if a record was written, so this
        // answers "has anything changed" without reading a body at all. The projection-and-hash path
        // below had to serialise the whole document first.
        if let Some(db) = bsc_graph::graph_db() {
            if let Ok(sig) = bsc_graph_store::signature(&db) {
                return serde_json::Value::String(sig);
            }
        }
        serde_json::Value::String(page_signature(&page_projection(bsc_graph::load())))
    })
    .await
}

/// The latest turn-boundary state per pane (`run`/`idle`), newest pane first — the in-process drop-in
