#[cfg(test)]
mod tests {
    use super::*;


    /// The projection drops the two fields that made the poll unaffordable, and keeps everything the
    /// page renders.
    ///
    /// MEASURED 2026-09-08 over the real store (1,401 records, 50.72 MB): `history` 16.20 MB and
    /// `tests` 14.16 MB — 60% of the document — against a page that reads neither. The remaining
    /// fields are the ones `AlgorithmsInspector`, `AlgorithmsKitGraph`, `AlgorithmsRail`,
    /// `classifyKind`, `crossGraphAdapter` and `knowledge.tsx` actually touch.
    #[test]
    fn the_projection_keeps_what_the_page_renders_and_drops_what_it_never_reads() {
        let doc = serde_json::json!({
            "version": 1,
            "edges": [{ "id": "e" }],
            "implementations": [{
                "id": "a.ts", "name": "A", "role": "algorithm", "tech": "typescript",
                "composes": ["b.ts"], "code": "export const a = 1;", "summary": "s", "ref": "r",
                "folder": "f", "tags": ["t"], "src": "src/a.ts", "domain": "d", "kind": "sort",
                // …and the bulk the page never touches:
                "history": [{ "rev": 1 }, { "rev": 2 }], "tests": [{ "src": "a huge test body" }],
                "rev": 7, "updatedAt": "now", "updatedBy": "someone", "build": { "verdict": "pass" }
            }]
        });
        let got = page_projection(doc);
        let rec = &got["implementations"][0];

        for keep in ["id", "name", "role", "tech", "composes", "summary", "ref", "folder", "tags", "src", "domain", "kind"] {
            assert!(rec.get(keep).is_some(), "the page reads `{keep}` — projecting it away is a rendering bug");
        }
        // `code` and `vizCode` go with them: 1,401 bodies shipped to render ONE is 19.31 MB of the
        // payload, and `graph_impl_source` fetches the selected record's source instead.
        for drop in ["history", "tests", "code", "vizCode", "rev", "updatedAt", "updatedBy", "build"] {
            assert!(rec.get(drop).is_none(), "`{drop}` reaches the webview on a 5-second poll: {rec}");
        }
        // The document's other keys survive — the page reads `edges`, and a version tells a reader what
        // shape they have.
        assert_eq!(got["edges"].as_array().map(Vec::len), Some(1));
        assert_eq!(got["version"], serde_json::json!(1));
    }

    /// A store whose implementations are absent or malformed must not panic the command — the page's
    /// whole degradation story is "keep rendering".
    #[test]
    fn the_projection_tolerates_a_document_that_is_not_the_shape_it_expects() {
        assert_eq!(page_projection(serde_json::json!({})), serde_json::json!({}));
        assert_eq!(
            page_projection(serde_json::json!({ "implementations": "not an array" }))["implementations"],
            serde_json::json!("not an array")
        );
        // A non-object record is passed through rather than dropped: losing it silently is the one
        // outcome worse than rendering something odd.
        let got = page_projection(serde_json::json!({ "implementations": [42] }));
        assert_eq!(got["implementations"][0], serde_json::json!(42));
    }

    /// The signature answers the poll's only question — "has anything the page renders changed?" — and
    /// it must be blind to everything else, or the short-circuit never fires.
    #[test]
    fn the_signature_moves_on_a_rendered_change_and_ignores_write_bookkeeping() {
        // `summary` stands in for "something the page renders"; `code` is deliberately NOT the probe
        // here, because the projection drops it and a signature over the projection cannot see it.
        let rec = |summary: &str, rev: i64| serde_json::json!({
            "implementations": [{ "id": "a.ts", "summary": summary, "code": "unchanged", "rev": rev,
                                  "history": [{ "rev": rev }], "updatedAt": "whenever" }]
        });
        let base = page_signature(&page_projection(rec("one", 1)));

        // EVERY write bumps `rev` and appends to `history`. If those moved the signature, the
        // short-circuit would fire approximately never and this whole change would buy nothing.
        assert_eq!(base, page_signature(&page_projection(rec("one", 2))), "bookkeeping must not read as a change");
        // …and a real edit must still move it, or an edit would stop showing up entirely, which is a
        // worse bug than the one being fixed.
        assert_ne!(base, page_signature(&page_projection(rec("two", 1))), "a rendered edit MUST move the signature");

        // A BODY-ONLY EDIT MUST STILL MOVE IT, through `codeHash`. Without that the index would sign
        // nothing a body edit touches — `code`, `rev`, `updatedAt` and `history` are all projected
        // away — the poll would short-circuit forever and a librarian's live edit would never appear,
        // which is the exact case this page's 5-second poll exists for.
        let body = |code: &str| serde_json::json!({
            "implementations": [{ "id": "a.ts", "summary": "same", "code": code }]
        });
        assert_ne!(
            page_signature(&page_projection(body("one"))),
            page_signature(&page_projection(body("two"))),
            "a body-only edit MUST move the signature, or a live edit never shows"
        );
        // …and the hash is what carries it, not the body — the index must stay body-free.
        let projected = page_projection(body("one"));
        let rec = &projected["implementations"][0];
        assert!(rec.get("code").is_none(), "the index must not carry bodies: {rec}");
        assert_eq!(rec["codeHash"].as_str().map(str::len), Some(64));

        // A record with NO source carries no hash — an empty string would hash to a constant and put
        // 64 pointless characters on every primitive that only carries a `ref`.
        let bare = page_projection(serde_json::json!({ "implementations": [{ "id": "b.ts" }] }));
        assert!(bare["implementations"][0].get("codeHash").is_none(), "no source ⇒ no hash");
    }


    /// WHAT `hydrateAlgorithms` PUTS IN THE STORE MUST BE ENOUGH FOR `resolveGraphSource` TO RESOLVE.
    ///
    /// The bug this exists for, in full: `graph_dump` served two consumers — the Algorithms page, which
    /// renders records, and the module RESOLVER, which turns a graph module's `@/…` import into source
    /// by matching `provides` and vendoring `code`. Projecting bodies out of `graph_dump` to make the
    /// page's 5-second poll affordable therefore stopped every record-provided module in the app from
    /// resolving — including the ones the Algorithms page is itself built from, so the page did not
    /// lose records, it stopped loading.
    ///
    /// Nothing caught it. Every test passed, the full gate passed, and the failure only exists once a
    /// webview asks the resolver for a specifier. So the guard is the CONTRACT between the two:
    /// whatever the resolver's feed carries must answer `provides` -> `code`, and the page's index must
    /// NOT (or the payload problem comes straight back).
    #[test]
    fn the_resolver_feed_carries_bodies_and_the_page_index_does_not() {
        let doc = serde_json::json!({ "implementations": [
            { "id": "m.ts", "provides": "@/features/x/m", "code": "export const m = 1;", "name": "m",
              "history": [{ "rev": 1 }], "tests": [{ "src": "…" }] },
            // A record that provides NOTHING is not resolver material and must not be carried.
            { "id": "plain.ts", "code": "export const p = 2;", "name": "plain" },
            // …nor is one whose `provides` is blank.
            { "id": "blank.ts", "provides": "   ", "code": "export const b = 3;", "name": "blank" },
        ]});

        // THE RESOLVER'S FEED — `graph_modules`' projection.
        let mods = modules_projection(&doc);
        let list = mods["implementations"].as_array().expect("an array");
        assert_eq!(list.len(), 1, "only records that PROVIDE something are resolver material: {list:?}");
        assert_eq!(list[0]["provides"], "@/features/x/m");
        assert_eq!(
            list[0]["code"], "export const m = 1;",
            "the resolver vendors `code`; without it every record-provided import resolves to null"
        );
        // …and it carries nothing else, because it is read at boot and bodies are already the bulk.
        let obj = list[0].as_object().expect("an object");
        assert_eq!(obj.len(), 3, "id, provides, code — and nothing else: {obj:?}");

        // THE PAGE'S INDEX — the other half of the contract. If bodies came back here the 50.76 MB
        // poll comes back with them.
        let page = page_projection(doc);
        let rec = &page["implementations"][0];
        assert!(rec.get("code").is_none(), "the page index must stay body-free: {rec}");
        assert!(rec.get("provides").is_some(), "…while still naming what each record provides");
    }

    #[test]
    fn graph_dump_reads_the_cli_store_and_always_yields_a_graph() {
        // #4078 — the command must resolve the SAME store the `bsc graph` CLI does (`BSC_GRAPH_STORE`,
        // else the home path), or the page and the librarian would silently read different files. It
        // calls `bsc_graph::load` for exactly that reason; this pins the behaviour that matters to the
