        assert!(g.get("implementations").is_some_and(|v| v.is_array()), "must fall back to the seed: {g}");

        match prev {
            Some(v) => std::env::set_var("BSC_GRAPH_STORE", v),
            None => std::env::remove_var("BSC_GRAPH_STORE"),
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

